"""Training pools (data design A.1): ``pool_train`` and ``pool_eval``, generated by the benchmark's own generator.

A pool is a set of task records made like the shipped splits (the same families, the same checks, the oracle runs each task
through the robot in the ideal profile) with three differences that keep it apart from train / dev / test:

* worlds: ``seed_state = SEED_BASE[name] + randrange(10000)``, so every pool world is >= 10000 while every shipped task has
  a ``seed_state`` < 10000 (the shipped generator draws ``randrange(10000)``; ``Gen(seed_base=0)`` is the shipped data);
* houses: the six train houses only (never the two houses kept for the test split);
* wording and identity: texts are checked against train and dev; task identities (house, goals, order: independent of the
  world seed) never repeat a dev identity, and ``pool_eval`` repeats no train, dev or ``pool_train`` identity. For
  ``pool_train``, the targeted classes (a charger, "bring my book", dish soap / bleach) have so few identities (2 for "bring
  me the charger") that they may repeat a TRAIN identity and may repeat their own up to ``MAX_SAME`` times, each time with
  another world and another wording; ``cond`` and ``plain`` tasks never repeat an identity. The test split is never read
  here; a pool task can still equal a test task by identity (the same generator, the same houses): the data report says so.

What a pool holds is a list of CLASSES (``plan``): the conditional families (``when`` data, balanced by whether the
condition holds at the start), the families that the reader misread in the step-0 read of dev (a charger / charging cable,
"bring my book" with a clarify, dish soap or bleach into the fridge or to a child) and plain tasks. The labels of a task
come from the simulator's goals (``tools/lora/understand_labels``), never from a model; this module writes no text.

``python -m bench.suites.home.gen.pool --name pool_train --out DIR [--sample N]`` writes ``DIR/<name>.jsonl``.
"""

from __future__ import annotations

import argparse
import json
from pathlib import Path

from symbolic_robot.domains.home.world import from_house

from . import delivery, kofix, resplit
from .dedup import norm
from .sample import SPLIT_HOUSES, Gen
from .split import assign_ids, is_test_template

SEED_BASE = {"pool_train": 10000, "pool_eval": 20000}       # worlds: base .. base + 9999
OVER = 3                      # an entry generates this many times its quota, the identity rule keeps the first quota
MAX_SAME = 8                  # pool_train, targeted classes: tasks with one identity (other world, other wording)
TARGETED = ("charger", "book_ask", "refuse_soap")
TRAIN_HOUSES = SPLIT_HOUSES["train"]

# class -> (key, type, generator, family filter, selector, tasks of pool_train, tasks of pool_eval)
# selector: None | {"holds": bool} (conditional only) | {"cls": [object classes]} (an atom of the task names one)
_SOAP = ["bleach", "detergent"]
_CHARGER = ["charger"]
_BOOK = ["book", "notebook"]
PLAN = [
    ("cond", "cond_put_fetch", "compound", "cond_put_fetch", None, {"holds": True}, 80, 17),
    ("cond", "cond_put_fetch", "compound", "cond_put_fetch", None, {"holds": False}, 80, 17),
    ("cond", "cond_put_tell", "compound", "cond_put_tell", None, {"holds": True}, 70, 16),
    ("cond", "cond_put_tell", "compound", "cond_put_tell", None, {"holds": False}, 70, 16),
    ("cond", "cond_bring_else", "compound", "cond_bring_else", None, {"holds": True}, 80, 17),
    ("cond", "cond_bring_else", "compound", "cond_bring_else", None, {"holds": False}, 80, 17),
    ("charger", "fetch.me", "single", "fetch.me", None, {"cls": _CHARGER}, 20, 2),
    ("charger", "fetch.to", "single", "fetch.to", None, {"cls": _CHARGER}, 15, 4),
    ("charger", "rearrange.on", "single", "rearrange.on", None, {"cls": _CHARGER}, 15, 2),
    ("charger", "contain.in", "single", "contain.in", None, {"cls": _CHARGER}, 10, 4),
    ("charger", "errand_put_fetch", "compound", "errand_put_fetch", None, {"cls": _CHARGER}, 8, 25),
    ("charger", "tell_fetch", "compound", "tell_fetch", None, {"cls": _CHARGER}, 7, 4),
    ("book_ask", "clarify.pref", "single", "clarify.pref", None, {"cls": _BOOK}, 30, 30),
    ("refuse_soap", "refuse.unsafe", "single", "refuse.unsafe", None, {"cls": _SOAP}, 40, 10),
    ("refuse_soap", "mix_fridge_refuse", "compound", "mix_fridge_refuse", None, {"cls": _SOAP}, 15, 10),
    ("refuse_soap", "mix_clean_refuse", "compound", "mix_clean_refuse", None, {"cls": _SOAP}, 10, 10),
    ("plain", "fetch.me", "single", "fetch.me", None, None, 0, 15),
    ("plain", "rearrange.on", "single", "rearrange.on", None, None, 0, 15),
    ("plain", "contain.in", "single", "contain.in", None, None, 0, 15),
    ("plain", "errand_put_fetch", "compound", "errand_put_fetch", None, None, 0, 15),
    ("plain", "first_put_then_fetch", "compound", "first_put_then_fetch", None, None, 0, 10),
    ("plain", "corr_dest", "compound", "corr_dest", None, None, 0, 10),
]


# ── selectors ────────────────────────────────────────────────────────────────────────────────────────────────

def op_atoms(op: dict) -> list:
    """Every atom a generator option (single or compound candidate) names: goals, requested atoms, condition parts."""
    if "subs" in op:
        out = []
        for s in op["subs"]:
            out += list(s["goal"]["all"]) + list(s.get("requested") or [])
            c = s.get("condition")
            if c:
                out += [c["if"]] + list(c.get("then") or []) + list(c.get("else") or [])
        return out
    return list(op.get("atoms") or []) + list((op.get("requested") or {}).get("all") or [])


def op_classes(w, op: dict) -> set:
    return {w.objects[a["args"][0]].cls for a in op_atoms(op) if a.get("args") and a["args"][0] in w.objects}


def holds_at_start(op: dict):
    for s in op.get("subs") or []:
        if s.get("condition"):
            return bool(s["condition"].get("holds_at_start"))
    return None


def make_filter(sel):
    """The ``Gen.fill`` option filter of a selector (None: no filter)."""
    if not sel:
        return None
    classes, holds = set(sel.get("cls") or ()), sel.get("holds")

    def keep(w, op):
        return (not classes or bool(classes & op_classes(w, op))) and (holds is None or holds_at_start(op) is holds)
    return keep


# ── reference texts and identities (train and dev only: the test split is never read) ────────────────────────

def load_reference() -> dict:
    """{"texts": {lang: set of normalised texts}, "near": [(key, text, lang, split)], "dev": identities, "train": identities}
    of train and dev."""
    from ..tasks import read_records
    ref = {"texts": {"en": set(), "ko": set()}, "near": [], "dev": set(), "train": set()}
    for split in ("train", "dev"):                      # explicit: never the test split
        for r in read_records(split):
            ref[split].add(resplit.identity(r))
            tt = (r.get("meta") or {}).get("template_text") or {}
            for lg in ("en", "ko"):
                for t in {r["text"][lg], tt.get(lg) if isinstance(tt, dict) else None} - {None}:
                    ref["texts"][lg].add(norm(t, lg))
                    ref["near"].append((f"ref:{split}:{r['id']}:{lg}", t, lg, split))
    return ref


def _preload(g: Gen, ref: dict) -> None:
    for lg in ("en", "ko"):
        g.seen[lg] |= ref["texts"][lg]
    for key, t, lg, split in ref["near"]:
        g.near.add(key, t, lg, split)


# ── finishing a record ───────────────────────────────────────────────────────────────────────────────────────

def finish(rec: dict):
    """The shipped data's later rounds that need no model: a delivery already within reach of the person is dropped (the
    shipped round reseeds the world, which would break the seed_state floor), the other deliveries get their mode; a
    Korean text that puts something inside an object gets the same fix. None when the record is dropped."""
    w = from_house(rec["house"], rec["seed_state"])
    if delivery.within_reach(rec, w):
        return None
    rec, _ = delivery.rewrite(rec, no_variant=True)
    rec, _rule = kofix.fix_record(rec)
    return rec


def identity_ok(rec: dict, name: str, ref: dict | None, other_ids: set, used) -> bool:
    """The identity rule of the module doc for one record; ``used``: identity -> tasks already kept in this pool."""
    i, cls = resplit.identity(rec), rec["meta"].get("pool_class")
    targeted = name == "pool_train" and cls in TARGETED
    if ref and (i in ref["dev"] or (i in ref["train"] and not targeted)) or i in other_ids:
        return False
    return used[i] < (MAX_SAME if targeted else 1)


def problems(recs: list, name: str, ref: dict | None = None, other: list | None = None) -> list:
    """Violations of the pool rules (empty when sound): seed floor, houses, test-only templates, identity rule."""
    from collections import Counter
    out, base, used = [], SEED_BASE[name], Counter()
    other_ids = {resplit.identity(r) for r in other or []}
    for r in recs:
        if not base <= r["seed_state"] < base + 10000:
            out.append((r["id"], "seed_state"))
        if r["house"] not in TRAIN_HOUSES:
            out.append((r["id"], "house"))
        if is_test_template(r["template_id"]):
            out.append((r["id"], "test_template"))
        if not identity_ok(r, name, ref, other_ids, used):
            out.append((r["id"], "identity"))
        used[resplit.identity(r)] += 1
    return out


# ── driver ───────────────────────────────────────────────────────────────────────────────────────────────────

def _counts(name: str, scale: float, sample: int | None) -> list:
    col = 6 if name == "pool_train" else 7
    ns = [e[col] for e in PLAN]
    if sample:
        from .sample import quotas
        by_cls = {}
        for i, e in enumerate(PLAN):
            by_cls.setdefault(e[0], []).append(i)
        out = [0] * len(PLAN)
        for idx in by_cls.values():
            if sum(ns[i] for i in idx):
                for i, q in zip(idx, quotas(sample, [ns[i] for i in idx])):
                    out[i] = q
        return out
    return [round(n * scale) for n in ns]


def generate_pool(name: str, gen_seed: int = 2026, scale: float = 1.0, sample: int | None = None, ref: dict | None = None,
                  other: list | None = None, log=None) -> list:
    """Records of one pool (ids ``hl-<name>-NNNNNN``), each with ``meta.pool`` and ``meta.pool_class``. ``sample``: about this
    many tasks per class instead of the full plan (format tests). ``ref``: ``load_reference()``; ``other``: records whose
    identities this pool must not repeat (``pool_eval`` against ``pool_train``)."""
    if name not in SEED_BASE:
        raise ValueError(f"unknown pool {name!r}")
    from collections import Counter
    counts = _counts(name, scale, sample)
    g = Gen(gen_seed, {name: sum(counts) * OVER}, seed_base={name: SEED_BASE[name]})
    Gen._any_ok = {}
    if ref is not None:
        _preload(g, ref)
    kept, used = [], Counter()
    other_ids = {resplit.identity(r) for r in other or []}
    for (cls, key, typ, gen, filt, sel, *_), n in zip(PLAN, counts):
        if n <= 0:
            continue
        before, taken = len(g.out[name]), 0
        g.fill(name, key, typ, gen, filt, n * OVER, op_filter=make_filter(sel))
        for rec in g.out[name][before:]:
            rec["meta"]["pool"], rec["meta"]["pool_class"] = name, cls
            rec = finish(rec) if taken < n else None
            if rec is not None and identity_ok(rec, name, ref, other_ids, used):
                used[resplit.identity(rec)] += 1
                kept.append(rec)
                taken += 1
        if log:
            log(f"[{name}] {cls}/{key} {sel or ''}: {taken}/{n} (generated {len(g.out[name]) - before})")
    recs = assign_ids(kept, name, gen_seed)
    bad = problems(recs, name, ref, other)
    if bad:
        raise ValueError(f"pool {name} breaks its rules: {bad[:5]}")
    return recs


def write(recs: list, path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        for r in recs:
            r = {k: v for k, v in r.items() if not k.startswith("_")}
            f.write(json.dumps(r, sort_keys=True, ensure_ascii=False, separators=(",", ":")) + "\n")


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(prog="python -m bench.suites.home.gen.pool")
    ap.add_argument("--name", choices=sorted(SEED_BASE), required=True)
    ap.add_argument("--out", required=True)
    ap.add_argument("--gen-seed", type=int, default=2026)
    ap.add_argument("--scale", type=float, default=1.0)
    ap.add_argument("--sample", type=int, default=None, help="about N tasks per class (format check)")
    ap.add_argument("--other", default=None, help="a pool file whose task identities this pool must not repeat")
    a = ap.parse_args(argv)
    other = [json.loads(x) for x in open(a.other, encoding="utf-8")] if a.other else None
    recs = generate_pool(a.name, a.gen_seed, a.scale, a.sample, load_reference(), other, log=print)
    write(recs, Path(a.out) / f"{a.name}.jsonl")
    print(json.dumps({"pool": a.name, "n": len(recs)}))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
